import { readdirSync, readFileSync, writeFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

// Reads every bars/<slug>/bar.json and bars/moments.json, and writes bars/INDEX.md. Run it with `pnpm gen:bars`.
const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");

/** A moment holds at most this many bars. A new bar must replace one, and the old one gets `superseded`. */
export const MAX_PER_MOMENT = 3;

export const HEADER = [
  "# Bar index",
  "",
  "Generated by scripts/gen-bars-index.mjs from every `bars/<slug>/bar.json` and `bars/moments.json`.",
  "Do not edit this file. Change a bar.json file, then run `pnpm gen:bars`.",
  "",
  "One section per moment that has a bar. Superseded bars are left out.",
].join("\n");

/** Every bar.json under `root`/bars, in folder-name order. Folders with no bar.json are skipped. */
export function readBars(root = ROOT) {
  const dir = path.join(root, "bars");
  const slugs = readdirSync(dir, { withFileTypes: true }).filter((d) => d.isDirectory()).map((d) => d.name).sort();
  const bars = [];
  for (const slug of slugs) {
    let text;
    try {
      text = readFileSync(path.join(dir, slug, "bar.json"), "utf8");
    } catch (e) {
      if (e.code === "ENOENT") continue;
      throw e;
    }
    bars.push(JSON.parse(text));
  }
  return bars;
}

/** The moment list in bars/moments.json under `root`. */
export function readMoments(root = ROOT) {
  return JSON.parse(readFileSync(path.join(root, "bars", "moments.json"), "utf8"));
}

const cell = (v) => String(v).replace(/\|/g, "\\|").replace(/\s*\n\s*/g, " ");
const rung = (r) => (Array.isArray(r) ? `${r[0]} to ${r[1]}` : String(r));

/** Pure: the text of bars/INDEX.md. Throws when a bar names an unknown moment or a moment holds more than MAX_PER_MOMENT bars. */
export function render(bars, moments) {
  const live = bars.filter((b) => b.superseded === undefined).sort((a, b) => (a.slug < b.slug ? -1 : a.slug > b.slug ? 1 : 0));
  const names = new Set(moments.map((m) => m.name));
  for (const b of live) for (const m of b.moments) if (!names.has(m)) throw new Error(`${b.slug}: unknown moment "${m}"`);
  const out = [HEADER];
  for (const m of moments) {
    const rows = live.filter((b) => b.moments.includes(m.name));
    if (rows.length === 0) continue;
    if (rows.length > MAX_PER_MOMENT) throw new Error(`${m.name}: ${rows.length} bars, at most ${MAX_PER_MOMENT}`);
    out.push(
      "",
      `## ${m.name}`,
      "",
      m.meaning,
      "",
      "| Bar | Kinds | Rung | Feel | Fits when | Wrong for | Folder |",
      "|---|---|---|---|---|---|---|",
      ...rows.map((b) => `| [${b.slug}](${b.slug}/index.html) | ${cell(b.kinds.join(", "))} | ${rung(b.rung)} | ${cell(b.feel)} | ${cell(b.fits)} | ${cell(b.wrongFor)} | \`bars/${b.slug}/\` |`),
    );
  }
  return `${out.join("\n")}\n`;
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  const out = path.join(ROOT, "bars", "INDEX.md");
  writeFileSync(out, render(readBars(), readMoments()));
  console.log(`Wrote ${path.relative(ROOT, out)}`);
}
